  "from collections import Counter\n\ndef word_frequency(text: str, top_n: int = 10) -> list[tuple[str, int]]:\n    words = text.lower().split()\n    cleaned = [w.strip(\".,!?;:\\\"'()-\") for w in words]\n    filtered = [w for w in cleaned if len(w) > 1]\n    return Counter(filtered).most_common(top_n)",
  "def topological_sort(graph: dict[str, list[str]]) -> list[str]:\n    visited: set[str] = set()\n    result: list[str] = []\n\n    def dfs(node: str) -> None:\n        if node in visited:\n            return\n        visited.add(node)\n        for neighbor in graph.get(node, []):\n            dfs(neighbor)\n        result.append(node)\n\n    for node in graph:\n        dfs(node)\n    return result[::-1]",
  "def run_length_encode(s: str) -> list[tuple[str, int]]:\n    if not s:\n        return []\n    result = []\n    current, count = s[0], 1\n    for ch in s[1:]:\n        if ch == current:\n            count += 1\n        else:\n            result.append((current, count))\n            current, count = ch, 1\n    result.append((current, count))\n    return result\n\ndef run_length_decode(encoded: list[tuple[str, int]]) -> str:\n    return \"\".join(ch * count for ch, count in encoded)",
